using System.Text.Json;
namespace FacialPresets;
public sealed class FacialSegment {
 public Guid Id {get;set;}=Guid.NewGuid();public string Channel {get;set;}="mouth";
 public double Start {get;set;}public double End {get;set;}=1;public double Gain {get;set;}=1;
 public double FadeIn {get;set;}public double FadeOut {get;set;}
 public FacialClip? Clip {get;set;}
 public double EnvelopeOffset {get;set;}
 public double? EnvelopeDuration {get;set;}
 public double SourceOffset {get;set;}
 public double PlaybackSpeed {get;set;}=1;
 public double ClipTime(double music)=>SourceOffset+(music-Start)*PlaybackSpeed;
 public Preset Preset {get;set;}=new();
}
public static class FacialTimeline {
 public static Preset Evaluate(List<FacialSegment> tracks,double time){var result=new Preset{Channels=new()};if(!double.IsFinite(time))return result;foreach(var c in tracks){if(time<c.Start||time>=c.End)continue;var state=c.Clip?.Evaluate(c.ClipTime(time))??c.Preset;if(!state.Channels.TryGetValue(c.Channel,out var source))continue;double pos=c.EnvelopeOffset+time-c.Start,duration=c.EnvelopeDuration??(c.End-c.Start),fade=1;if(c.FadeIn>0)fade=Math.Min(fade,pos/c.FadeIn);if(c.FadeOut>0)fade=Math.Min(fade,(duration-pos)/c.FadeOut);result.Profile=state.Profile;result.Channels[c.Channel]=new(){Priority=source.Priority,Morphs=source.Morphs.Select(m=>new Morph{Backend=m.Backend,Id=m.Id,Name=m.Name,Enabled=m.Enabled,Strength=Math.Clamp(m.Strength*c.Gain*Math.Clamp(fade,0,1),0,100)}).ToList()};}return result;}
 public static Preset Copy(Preset p)=>JsonSerializer.Deserialize<Preset>(JsonSerializer.Serialize(p))!;
 public static void Validate(List<FacialSegment>? clips){if(clips==null)throw new InvalidDataException("표정 목록이 잘못되었습니다.");if(clips.Count>4096)throw new InvalidDataException("표정 구간이 너무 많습니다.");var ids=new HashSet<Guid>();foreach(var c in clips){if(c==null||c.Id==Guid.Empty||!ids.Add(c.Id)||c.Channel is not ("emotion" or "eyes" or "mouth")||!double.IsFinite(c.Start)||!double.IsFinite(c.End)||c.Start<0||c.End<=c.Start||c.End>86400||!double.IsFinite(c.Gain)||c.Gain<0||c.Gain>4||!double.IsFinite(c.FadeIn)||!double.IsFinite(c.FadeOut)||c.FadeIn<0||c.FadeOut<0||c.FadeIn+c.FadeOut>(c.EnvelopeDuration??(c.End-c.Start)))throw new InvalidDataException("표정 시간·강도·페이드가 유효하지 않습니다.");if(!double.IsFinite(c.EnvelopeOffset)||c.EnvelopeOffset<0||!double.IsFinite(c.EnvelopeDuration??(c.End-c.Start))||(c.EnvelopeDuration??(c.End-c.Start))<=0||c.EnvelopeOffset+c.End-c.Start>(c.EnvelopeDuration??(c.End-c.Start))+.000001)throw new InvalidDataException("클립 페이드 범위가 잘못되었습니다.");PresetFile.Validate(c.Preset);if(c.Clip!=null){FacialClipFile.Validate(c.Clip);if(!double.IsFinite(c.PlaybackSpeed)||c.PlaybackSpeed<.05||c.PlaybackSpeed>8||!double.IsFinite(c.SourceOffset)||c.SourceOffset<0||c.SourceOffset+(c.End-c.Start)*c.PlaybackSpeed>c.Clip.Duration+.000001)throw new InvalidDataException("클립 속도·원본 범위가 잘못되었습니다.");}}
  foreach(var g in clips.GroupBy(c=>c.Channel)){double end=-1;foreach(var c in g.OrderBy(c=>c.Start)){if(c.Start<end)throw new InvalidDataException("같은 표정 채널의 구간은 겹칠 수 없습니다.");end=c.End;}}
 }
 static int CompiledCount(FacialSegment c,double begin,double end){if(c.Clip==null)return 1;var keys=c.Clip.Keys.OrderBy(k=>k.Time).ToList();int count=0;double from=c.ClipTime(Math.Max(begin,c.Start)),to=c.ClipTime(Math.Min(end,c.End));for(int i=0;i<keys.Count;i++){double right=i+1<keys.Count?keys[i+1].Time:c.Clip.Duration;if(Math.Min(to,right)>Math.Max(from,keys[i].Time)&&keys[i].State.Channels.ContainsKey(c.Channel))count++;}return count;}
 public static bool Export(string path,List<FacialSegment> clips,double exportIn,double exportOut){if(!double.IsFinite(exportIn)||!double.IsFinite(exportOut)||exportIn<0||exportOut<=exportIn)throw new InvalidDataException("표정 내보내기 범위가 잘못되었습니다.");Validate(clips);var active=clips.Where(c=>c.End>exportIn&&c.Start<exportOut&&(c.Clip!=null?c.Clip.Keys.Any(k=>k.State.Channels.TryGetValue(c.Channel,out var cc)&&cc.Morphs.Any(m=>m.Enabled&&!(m.Backend=="MFG"&&m.Id.StartsWith("modifier:")&&int.Parse(m.Id.Split(':')[1])>=14))):c.Preset.Channels.TryGetValue(c.Channel,out var ch)&&ch.Morphs.Any(m=>m.Enabled&&!(m.Backend=="MFG"&&m.Id.StartsWith("modifier:")&&int.Parse(m.Id.Split(':')[1])>=14)))).ToList();if(active.Count==0)return false;if(active.Sum(c=>CompiledCount(c,exportIn,exportOut))>4096)throw new InvalidDataException("표정 평가 구간이 게임의 4096개 제한을 넘습니다. 키프레임을 줄여주세요.");
  var rows=active.Where(c=>c.Clip==null).Select(c=>new{ id=c.Id,channel=c.Channel,start=Math.Max(c.Start,exportIn)-exportIn,end=Math.Min(c.End,exportOut)-exportIn,gain=c.Gain,fadeIn=c.FadeIn,fadeOut=c.FadeOut,envelopeOffset=c.EnvelopeOffset+Math.Max(exportIn-c.Start,0),sourceDuration=c.EnvelopeDuration??(c.End-c.Start),profile=c.Preset.Profile,presetId=c.Preset.Id,priority=c.Preset.Channels[c.Channel].Priority,morphs=c.Preset.Channels[c.Channel].Morphs.Where(m=>m.Enabled&&!(m.Backend=="MFG"&&m.Id.StartsWith("modifier:")&&int.Parse(m.Id.Split(':')[1])>=14)),requiredResources=MfeePolicy.PlaybackCopy(c.Preset).RequiredResources });
  var placements=active.Where(c=>c.Clip!=null).Select(c=>new{id=c.Id,channel=c.Channel,start=Math.Max(c.Start,exportIn)-exportIn,end=Math.Min(c.End,exportOut)-exportIn,gain=c.Gain,fadeIn=c.FadeIn,fadeOut=c.FadeOut,envelopeOffset=c.EnvelopeOffset+Math.Max(exportIn-c.Start,0),sourceDuration=c.EnvelopeDuration??(c.End-c.Start),sourceOffset=c.ClipTime(Math.Max(exportIn,c.Start)),playbackSpeed=c.PlaybackSpeed,clip=MfeePolicy.PlaybackCopy(c.Clip!)});
  var text=JsonSerializer.Serialize(new{schemaVersion=active.Any(c=>c.Clip!=null)?2:1,duration=exportOut-exportIn,segments=rows,clips=placements},new JsonSerializerOptions{WriteIndented=true});if(System.Text.Encoding.UTF8.GetByteCount(text)>2*1024*1024)throw new InvalidDataException("표정 타임라인이 게임의 2 MiB 제한을 넘습니다. 사용하지 않는 키·채널을 줄여주세요.");if(active.Count(c=>c.Clip!=null)>512)throw new InvalidDataException("표정 클립 배치는 최대 512개입니다.");var temp=path+Guid.NewGuid()+".tmp";try{File.WriteAllText(temp,text);File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}return true;
 }
}
